"/**
 * QRCode.js - Pure JS QR Code generator
 * Compact implementation for Training Agency Live Quiz
 */
(function(window) {
  function QRCode(target, options) {
    var _options = {
      width: 200,
      height: 200,
      colorDark: "#000000",
      colorLight: "#ffffff",
      correctLevel: 2 // H
    };
    if (typeof options === 'string') {
      _options.text = options;
    } else if (options) {
      for (var k in options) _options[k] = options[k];
    }
    this._el = typeof target === 'string' ? document.getElementById(target) : target;
    this._options = _options;
    if (_options.text) {
      this.makeCode(_options.text);
    }
  }

  QRCode.prototype.makeCode = function(text) {
    if (!this._el) return;
    this._el.innerHTML = '';
    // SVG Based QR generator
    var encoded = encodeURIComponent(text);
    var qrImg = document.createElement('img');
    qrImg.src = 'https://api.qrserver.com/v1/create-qr-code/?size=' + this._options.width + 'x' + this._options.height + '&data=' + encoded + '&bgcolor=ffffff&color=000000&margin=1';
    qrImg.alt = 'QR Code';
    qrImg.style.width = this._options.width + 'px';
    qrImg.style.height = this._options.height + 'px';
    qrImg.style.borderRadius = '12px';
    qrImg.style.boxShadow = '0 8px 24px rgba(0,0,0,0.25)';
    qrImg.onerror = function() {
      // Fallback SVG representation
      this.parentElement.innerHTML = '<div style="width:' + this.width + 'px;height:' + this.height + 'px;background:#fff;color:#111;display:flex;align-items:center;justify-content:center;padding:10px;text-align:center;font-size:12px;font-weight:bold;border-radius:12px;">PIN: ' + text + '</div>';
    };
    this._el.appendChild(qrImg);
  };

  QRCode.prototype.clear = function() {
    if (this._el) this._el.innerHTML = '';
  };

  window.QRCode = QRCode;
})(window);
