"/**
 * Scoring Engine - Implements PRD Section 6
 * Formula: Score = Math.round(Base Point * (Remaining Time / Total Time))
 * Wrong answer = 0
 */
class ScoringEngine {
  /**
   * Calculate score for a participant submission
   * @param {boolean} isCorrect - whether answer matches question correct_answer
   * @param {number} responseTimeSeconds - time taken by participant to answer in seconds
   * @param {number} totalTimeLimitSeconds - question total time limit (e.g., 20)
   * @param {number} basePoint - base question points (default 1000)
   * @returns {number} calculated score integer
   */
  static calculateScore(isCorrect, responseTimeSeconds, totalTimeLimitSeconds = 20, basePoint = 1000) {
    if (!isCorrect) {
      return 0;
    }

    if (totalTimeLimitSeconds <= 0) totalTimeLimitSeconds = 20;

    // Remaining time
    const remainingTime = Math.max(0, totalTimeLimitSeconds - responseTimeSeconds);

    // Speed ratio: answers within 0.5s get max points (1000), minimum floor is 40% of basePoint for correct answers
    const ratio = Math.min(1, Math.max(0.4, remainingTime / totalTimeLimitSeconds));

    const calculated = Math.round(basePoint * ratio);
    return Math.min(basePoint, Math.max(0, calculated));
  }

  /**
   * Calculate leaderboard rank order and streaks
   * @param {Array} players - list of player objects
   * @returns {Array} sorted players with ranks
   */
  static sortLeaderboard(players = []) {
    return [...players]
      .sort((a, b) => {
        if (b.total_score !== a.total_score) {
          return b.total_score - a.total_score;
        }
        // Tie breaker by correct count
        return (b.correct_count || 0) - (a.correct_count || 0);
      })
      .map((p, index) => ({
        ...p,
        rank: index + 1
      }));
  }
}

window.ScoringEngine = ScoringEngine;
