"/**
 * Realtime Event Bus - Supports BroadcastChannel (Multi-tab local) and Supabase Realtime
 */
class RealtimeBus {
  constructor() {
    this.channelName = 'ta_live_quiz_channel';
    this.listeners = new Map();
    this.bc = null;

    if (typeof BroadcastChannel !== 'undefined') {
      try {
        this.bc = new BroadcastChannel(this.channelName);
        this.bc.onmessage = (event) => {
          if (event && event.data) {
            this._dispatch(event.data.type, event.data.payload, false);
          }
        };
      } catch (e) {
        console.warn('BroadcastChannel error, fallback to storage events', e);
      }
    }

    // Fallback cross-tab storage listener
    window.addEventListener('storage', (e) => {
      if (e.key === 'ta_realtime_event' && e.newValue) {
        try {
          const data = JSON.parse(e.newValue);
          this._dispatch(data.type, data.payload, false);
        } catch (err) {}
      }
    });
  }

  /**
   * Broadcast an event to all subscribers and other open tabs/windows
   */
  emit(type, payload = {}) {
    const message = { type, payload, timestamp: Date.now() };

    // 1. Dispatch locally to current window
    this._dispatch(type, payload, true);

    // 2. BroadcastChannel to other tabs
    if (this.bc) {
      try {
        this.bc.postMessage(message);
      } catch (e) {}
    }

    // 3. Fallback Storage event trigger
    try {
      localStorage.setItem('ta_realtime_event', JSON.stringify(message));
    } catch (e) {}
  }

  /**
   * Register an event listener
   */
  on(type, callback) {
    if (!this.listeners.has(type)) {
      this.listeners.set(type, []);
    }
    this.listeners.get(type).push(callback);
    return () => this.off(type, callback);
  }

  /**
   * Unregister an event listener
   */
  off(type, callback) {
    if (!this.listeners.has(type)) return;
    const list = this.listeners.get(type).filter(cb => cb !== callback);
    this.listeners.set(type, list);
  }


