      status: 'LOBBY', // WAITING, LOBBY, QUESTION, RESULT, LEADERBOARD, FINISHED, CANCELLED
      current_question_index: 0,
      total_questions: quiz.questions.length,
      questions: JSON.parse(JSON.stringify(quiz.questions)),
      players: [],
      current_answers: {}, // playerId -> answer data
      start_time: new Date().toISOString(),
      max_participants: 50
    };

    // Save active game to storage for multi-tab recovery
    this.saveActiveSession();

    // Broadcast GAME_CREATED event
    window.realtimeBus.emit('GAME_CREATED', this.getPublicGameState());
    return this.activeGame;
  }"

